import sys
from pathlib import Path
sys.path.insert(0, str(Path("..").resolve()))

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

# --- 1. Load data ---
df = pd.read_csv("../data/phishing.csv")
print(f"Shape: {df.shape}")
print(df.head())

# --- 2. Info ---
print(df.info())
print(df.describe())

# --- 3. Missing values ---
print(df.isnull().sum())

# --- 4. Class balance ---
print(df["Result"].value_counts())
df["Result"].value_counts().plot(kind="bar", title="Class Distribution")
plt.show()

# --- 5. Feature distributions ---
from src.data_cleaning import FEATURE_COLUMNS
fig, axes = plt.subplots(6, 5, figsize=(18, 20))
for i, col in enumerate(FEATURE_COLUMNS):
    ax = axes[i // 5][i % 5]
    df[col].value_counts().sort_index().plot(kind="bar", ax=ax, color="#2563eb", edgecolor="white")
    ax.set_title(col, fontsize=8)
    ax.tick_params(labelsize=7)
plt.tight_layout()
plt.savefig("../results/feature_distributions.png", dpi=100, bbox_inches="tight")
plt.show()

# --- 6. Correlation heatmap ---
fig, ax = plt.subplots(figsize=(14, 12))
corr = df[FEATURE_COLUMNS + ["Result"]].corr()
sns.heatmap(corr, cmap="RdBu_r", center=0, linewidths=0.3, ax=ax)
ax.set_title("Feature Correlation Matrix")
plt.tight_layout()
plt.savefig("../results/correlation_heatmap.png", dpi=100, bbox_inches="tight")
plt.show()
